CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, login VARCHAR(40) NOT NULL UNIQUE, phone VARCHAR(11) NULL UNIQUE, wechat_openid VARCHAR(100) NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, nickname VARCHAR(40) NOT NULL, role VARCHAR(12) NOT NULL DEFAULT 'USER', status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE', verified_until DATETIME NULL, created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS roster (student_no VARCHAR(40) PRIMARY KEY, nickname VARCHAR(40) NOT NULL, expires_at DATETIME NOT NULL, consumed_at DATETIME NULL);
CREATE TABLE IF NOT EXISTS phone_codes (phone VARCHAR(11) NOT NULL, student_no VARCHAR(40) NOT NULL, code_hash CHAR(64) NOT NULL, expires_at DATETIME NOT NULL, sent_at DATETIME NOT NULL, attempts INT NOT NULL DEFAULT 0, PRIMARY KEY(phone,student_no));
CREATE TABLE IF NOT EXISTS password_reset_codes (phone VARCHAR(11) PRIMARY KEY, code_hash CHAR(64) NOT NULL, expires_at DATETIME NOT NULL, sent_at DATETIME NOT NULL, attempts INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions (sid VARCHAR(128) PRIMARY KEY, user_id BIGINT UNSIGNED NULL, data JSON NOT NULL, expires_at DATETIME NOT NULL, INDEX(user_id));
CREATE TABLE IF NOT EXISTS categories (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, icon VARCHAR(24) NOT NULL);
CREATE TABLE IF NOT EXISTS locations (id INT PRIMARY KEY, name VARCHAR(50) NOT NULL);
CREATE TABLE IF NOT EXISTS assets (id CHAR(36) PRIMARY KEY, owner_id BIGINT UNSIGNED NOT NULL, filename VARCHAR(100) NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, seller_id BIGINT UNSIGNED NOT NULL, category_id INT NOT NULL, location_id INT NOT NULL, title VARCHAR(60) NOT NULL, description TEXT NOT NULL, condition_code VARCHAR(30) NOT NULL, price_cents INT UNSIGNED NOT NULL, negotiable BOOLEAN NOT NULL DEFAULT 1, images JSON NOT NULL, status VARCHAR(24) NOT NULL DEFAULT 'PENDING_REVIEW', version INT NOT NULL DEFAULT 1, review_reason VARCHAR(500) NULL, created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), FOREIGN KEY(seller_id) REFERENCES users(id), FOREIGN KEY(category_id) REFERENCES categories(id), FOREIGN KEY(location_id) REFERENCES locations(id), INDEX(status,created_at), CHECK(price_cents > 0));
CREATE TABLE IF NOT EXISTS favorites (user_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,product_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS conversations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL, buyer_id BIGINT UNSIGNED NOT NULL, seller_id BIGINT UNSIGNED NOT NULL, sequence INT NOT NULL DEFAULT 0, buyer_read INT NOT NULL DEFAULT 0, seller_read INT NOT NULL DEFAULT 0, updated_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3), UNIQUE(product_id,buyer_id), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS offers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, conversation_id BIGINT UNSIGNED NOT NULL, proposer_id BIGINT UNSIGNED NOT NULL, recipient_id BIGINT UNSIGNED NOT NULL, amount_cents INT UNSIGNED NOT NULL, status VARCHAR(24) NOT NULL DEFAULT 'PENDING', product_version INT NOT NULL, expires_at DATETIME NOT NULL, purchase_deadline DATETIME NULL, created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(conversation_id) REFERENCES conversations(id), INDEX(status,expires_at));
CREATE TABLE IF NOT EXISTS messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, conversation_id BIGINT UNSIGNED NOT NULL, sequence INT NOT NULL, sender_id BIGINT UNSIGNED NULL, text VARCHAR(2000) NOT NULL DEFAULT '', offer_id BIGINT UNSIGNED NULL, client_id VARCHAR(64) NULL, created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3), UNIQUE(conversation_id,sequence), UNIQUE(sender_id,client_id), FOREIGN KEY(conversation_id) REFERENCES conversations(id));
CREATE TABLE IF NOT EXISTS orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_no VARCHAR(40) NOT NULL UNIQUE, product_id BIGINT UNSIGNED NOT NULL, buyer_id BIGINT UNSIGNED NOT NULL, seller_id BIGINT UNSIGNED NOT NULL, offer_id BIGINT UNSIGNED NULL UNIQUE, amount_cents INT UNSIGNED NOT NULL, snapshot JSON NOT NULL, status VARCHAR(24) NOT NULL DEFAULT 'PENDING_ACCEPT', previous_status VARCHAR(24) NULL, meeting VARCHAR(250) NOT NULL, meetup_at DATETIME NULL, meetup_location_id INT NULL, meetup_reminded_at DATETIME NULL, meetup_proposed_at DATETIME NULL, meetup_proposed_location_id INT NULL, meetup_proposed_by BIGINT UNSIGNED NULL, accept_deadline DATETIME NOT NULL, reason VARCHAR(500) NULL, created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), FOREIGN KEY(product_id) REFERENCES products(id), INDEX(status,accept_deadline), INDEX(status,meetup_at));
CREATE TABLE IF NOT EXISTS order_reviews (order_id BIGINT UNSIGNED PRIMARY KEY, buyer_id BIGINT UNSIGNED NOT NULL, seller_id BIGINT UNSIGNED NOT NULL, score TINYINT UNSIGNED NOT NULL, created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(buyer_id) REFERENCES users(id), FOREIGN KEY(seller_id) REFERENCES users(id), INDEX(seller_id), CHECK(score BETWEEN 1 AND 5));
CREATE TABLE IF NOT EXISTS product_reservations (product_id BIGINT UNSIGNED PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL UNIQUE, FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE IF NOT EXISTS order_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, actor_id BIGINT UNSIGNED NULL, status VARCHAR(24) NOT NULL, detail VARCHAR(500) NOT NULL, created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE IF NOT EXISTS idempotency_keys (user_id BIGINT UNSIGNED NOT NULL, request_key VARCHAR(80) NOT NULL, request_hash CHAR(64) NOT NULL, order_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(user_id,request_key));
CREATE TABLE IF NOT EXISTS reports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, reporter_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, reason VARCHAR(1000) NOT NULL, status VARCHAR(16) DEFAULT 'PENDING', resolution VARCHAR(1000) NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, admin_id BIGINT UNSIGNED NOT NULL, action VARCHAR(40) NOT NULL, target_id VARCHAR(40) NOT NULL, reason VARCHAR(1000) NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, text VARCHAR(500) NOT NULL, target_path VARCHAR(200) NULL, read_at DATETIME NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, INDEX(user_id,read_at));
